"""One-time authoring record for approved Domain 3 Lesson 2; never regenerates Lesson 1."""
from pathlib import Path
import json
P=lambda en,th:dict(en=en,th=th)
T=lambda p:dict(kind='text',text=P(*p))
R=lambda *cells:[P(*c) for c in cells]
slides=[]
def add(suffix,title,lead,rows,deep,points,foot,refs):
 i=len(slides)+1
 slides.append(dict(id=f'slide-d3-02-0{i}-{suffix}',title=P(*title),rendererId='interactive' if i==8 else 'text',layoutId='default',blocks=[T(lead),dict(kind='table',caption=P('Evidence, decisions and their limits','หลักฐาน การตัดสินใจ และขอบเขต'),columns=[P('Concept / condition','แนวคิด / เงื่อนไข'),P('Application','การนำไปใช้'),P('Reason / distinction','เหตุผล / ข้อแตกต่าง')],rows=rows),T(deep),dict(kind='list',items=[P(*p) for p in points]),T(foot)],referenceIds=refs,review=dict(status='approved',reviewedRevision='1')))

add('mover-before-after',('A new role does not justify keeping every old permission.','ย้ายหน้าที่แล้ว ไม่ได้แปลว่าควรเก็บทุกสิทธิ์เดิม'),('A Finance employee moves to IT; reporting access still remains six months later.','พนักงาน Finance ย้ายไป IT แต่หกเดือนต่อมายังใช้สิทธิ์อ่านรายงานการเงินเดิมได้'),[
 R(('Excessive Permissions','สิทธิ์มากเกินความจำเป็น'),('Access exceeds current work requirements.','สิทธิ์เกินกว่าที่งานปัจจุบันต้องใช้'),('Review the actual task and effective rights.','เทียบงานจริงกับสิทธิ์ที่ใช้ได้จริง')),
 R(('Unused Accounts','บัญชีที่ไม่ได้ใช้งาน'),('No use observed within the defined context.','ไม่พบการใช้ในช่วงหรือบริบทที่กำหนด'),('Inactivity alone does not establish missing ownership.','การไม่ใช้งานเพียงอย่างเดียวไม่ได้ยืนยันว่าขาดผู้รับผิดชอบ')),
 R(('Inappropriate Access','สิทธิ์ไม่เหมาะสม'),('A resource or action does not fit the assigned responsibility.','ทรัพยากรหรือรายการที่ให้ใช้ไม่สอดคล้องกับหน้าที่'),('Not every inappropriate grant is simply a large number of permissions.','สิทธิ์ไม่เหมาะสมไม่ได้หมายถึงมีจำนวนสิทธิ์มากเสมอไป')),
 R(('Role Changes','หน้าที่เปลี่ยน'),('Access may not yet reflect the new assignment.','สิทธิ์อาจยังไม่สอดคล้องกับงานใหม่'),('Reassess additions and removals.','พิจารณาทั้งสิทธิ์ที่ควรเพิ่มและถอน')),
 R(('Privilege Accumulation','สิทธิ์เก่าสะสม'),('New grants are added while unnecessary old rights remain.','เพิ่มสิทธิ์ใหม่แต่ยังเก็บสิทธิ์เดิมที่หมดความจำเป็น'),('Retain old rights only when current need is justified.','เก็บสิทธิ์เดิมได้เมื่อมีเหตุผลรองรับความจำเป็นปัจจุบัน')),
 R(('Orphaned Accounts','บัญชีที่ขาดผู้รับผิดชอบที่เหมาะสม'),('An account lacks appropriate ownership, governance or identity linkage.','บัญชีขาดผู้รับผิดชอบ การกำกับ หรือการเชื่อมกับ Identity ที่เหมาะสม'),('A known employee with stale rights is not necessarily an orphaned identity.','พนักงานที่ระบุตัวได้แต่สิทธิ์ค้าง ไม่จำเป็นต้องเป็น Identity ที่ขาดผู้รับผิดชอบ'))],
 ('When work changes, compare the access actually held with the current assignment. In the source example a Finance employee moved to IT six months ago but still reaches the Financial Reporting System. If that reporting access is no longer justified, an authorized change should remove it while enabling the IT work that is now needed. Adding the new role without reassessing the old grant can accumulate unnecessary privileges. Some previous access may remain legitimately justified by continuing duties; do not remove everything merely because a job title changed. The source identifies six review findings, retained in the table. This example concerns stale permissions, not automatic proof of an orphaned identity or an incident. The six-month delay describes what happened, not a recommended review interval.',
 'เมื่อหน้าที่เปลี่ยน ให้เทียบสิทธิ์ที่ใช้ได้จริงกับงานปัจจุบัน ตัวอย่างต้นฉบับคือพนักงานย้ายจาก Finance ไป IT มาหกเดือน แต่ยังเข้า Financial Reporting System ได้ หากไม่มีความจำเป็นใช้รายงานนั้นแล้ว ผู้มีอำนาจควรปรับถอนสิทธิ์เดิม พร้อมให้สิทธิ์ที่งาน IT ต้องใช้ การเพิ่ม Role ใหม่โดยไม่ทบทวนสิทธิ์เก่าทำให้สิทธิ์ที่ไม่จำเป็นสะสมได้ บางสิทธิ์เดิมอาจยังมีเหตุผลรองรับจากหน้าที่ที่ทำต่อ จึงไม่ควรถอนทุกอย่างเพียงเพราะชื่อตำแหน่งเปลี่ยน ตารางเก็บสิ่งที่ต้นฉบับระบุว่าการ Review ตรวจพบได้ทั้งหกอย่าง ตัวอย่างนี้เป็นปัญหาสิทธิ์ค้าง ไม่ใช่หลักฐานอัตโนมัติว่า Identity ขาดผู้รับผิดชอบหรือเกิด Incident แล้ว ส่วนหกเดือนเป็นเวลาที่ผ่านไปในเรื่อง ไม่ใช่คำแนะนำให้รอทบทวนตามช่วงนั้น'),
 [('Compare duties with effective access.','เทียบหน้าที่กับสิทธิ์ที่มีผลจริง'),('Remove unjustified rights; retain justified work access.','ถอนสิทธิ์ที่หมดความจำเป็น และคงสิทธิ์ที่งานยังต้องใช้'),('Record the decision and verify the change.','บันทึกผลตัดสินใจและตรวจผลการปรับสิทธิ์')],
 ('Finance reporting is outside the new task in this example; other continuing duties may differ.','ตัวอย่างนี้งานใหม่ไม่ต้องอ่านรายงาน Finance แต่หน้าที่ที่ทำต่อในกรณีอื่นอาจต่างกัน'),['d3-notes','d3-summary','identity-lifecycle'])

add('review-apply-verify',('A review decision must become a verified access change.','ผลทบทวนต้องนำไปสู่การปรับสิทธิ์ที่ตรวจยืนยันได้'),('A rejected entitlement in a spreadsheet is not the same as revoked access.','การระบุว่าไม่อนุมัติสิทธิ์ใน Spreadsheet ยังไม่เท่ากับถอนสิทธิ์ในระบบ'),[
 R(('Evidence and current need','หลักฐานและความจำเป็นปัจจุบัน'),('Compare entitlements with role, project and contract need.','เทียบสิทธิ์กับหน้าที่ โครงการ และความจำเป็นตามสัญญา'),('Use trustworthy, current records and an accountable reviewer.','ใช้ข้อมูลปัจจุบันที่เชื่อถือได้และมีผู้ทบทวนรับผิดชอบ')),
 R(('Authorized decision','การตัดสินใจตามอำนาจ'),('Retain, change or remove access with a reason.','คง ปรับ หรือถอนสิทธิ์พร้อมเหตุผล'),('Retaining justified access can be a valid result.','การคงสิทธิ์ที่ยังจำเป็นเป็นผลทบทวนที่ถูกต้องได้')),
 R(('Apply the decision','นำผลไปดำเนินการ'),('Responsible administrators or authorized automation update the grant.','ผู้ดูแลหรือระบบอัตโนมัติที่ได้รับอนุญาตปรับสิทธิ์'),('A signed review alone does not reconfigure an application.','ลงนามผลทบทวนอย่างเดียวไม่ได้เปลี่ยนสิทธิ์ในแอป')),
 R(('Verify and record','ตรวจผลและบันทึก'),('Check the intended allowed and denied actions.','ตรวจทั้งรายการที่ควรทำได้และควรถูกปฏิเสธ'),('Keep evidence of decision, implementation and result.','เก็บหลักฐานการตัดสินใจ การลงมือปรับ และผลตรวจ'))],
 ('An access review evaluates whether existing entitlements remain justified. A designated reviewer considers current responsibilities and reliable entitlement information, then records an authorized retain, change or remove decision with a reason. The responsible administrator or authorized automation must apply that decision to the relevant system. Verification then checks whether effective access matches the approved result, including work that should remain possible. For example, marking obsolete reporting access as rejected in a spreadsheet does not prove the reporting application now denies it. Keep records that connect the reviewer, decision, implementation and verification. Automated completion messages are evidence to assess, not a guarantee that every downstream system changed successfully. A review may legitimately retain access; success is justified, enforced access rather than removal of the largest number of rights.',
 'Access review ประเมินว่าสิทธิ์ที่มีอยู่ยังมีเหตุผลรองรับหรือไม่ ผู้ทบทวนที่มีหน้าที่ตามนโยบายพิจารณางานปัจจุบันและข้อมูลสิทธิ์ที่เชื่อถือได้ แล้วบันทึกว่าจะคง ปรับ หรือถอนสิทธิ์พร้อมเหตุผล จากนั้นผู้ดูแลหรือระบบอัตโนมัติที่ได้รับอนุญาตต้องนำผลไปปรับในระบบที่เกี่ยวข้อง และตรวจว่า Effective access ตรงกับผลที่อนุมัติ รวมถึงงานที่ยังควรทำได้ ตัวอย่างเช่น การทำเครื่องหมายไม่อนุมัติสิทธิ์รายงานเดิมใน Spreadsheet ไม่ได้พิสูจน์ว่าแอปรายงานปฏิเสธสิทธิ์นั้นแล้ว ควรเก็บข้อมูลที่เชื่อมผู้ทบทวน ผลตัดสินใจ การลงมือปรับ และการตรวจยืนยัน ข้อความว่างานอัตโนมัติเสร็จแล้วเป็นหลักฐานที่ต้องพิจารณา ไม่ใช่การรับประกันว่าทุกระบบปลายทางเปลี่ยนสำเร็จ การ Review อาจคงสิทธิ์ไว้ได้ เป้าหมายคือสิทธิ์ที่มีเหตุผลและถูกบังคับใช้จริง ไม่ใช่ถอนให้ได้จำนวนมากที่สุด'),
 [('A decision needs an authorized owner.','ผลตัดสินใจต้องมีผู้รับผิดชอบตามอำนาจ'),('Applying and verifying are distinct responsibilities.','การปรับสิทธิ์กับการตรวจผลเป็นคนละหน้าที่'),('Record justified retention as well as removal.','บันทึกเหตุผลทั้งการคงและถอนสิทธิ์')],
 ('Review → authorized decision → implementation → verification is this illustrative workflow.','ทบทวน → ตัดสินใจตามอำนาจ → ปรับสิทธิ์ → ตรวจผล เป็นกระบวนการตัวอย่างนี้'),['d3-notes','identity-lifecycle','nist-csf'])

add('activity-and-ownership',('Usage and ownership answer different questions.','การใช้งานกับผู้รับผิดชอบเป็นคนละคำถาม'),('An active account can be unmanaged; an unused account can still have a justified owner.','บัญชีที่ใช้งานอยู่อาจขาดการกำกับ ส่วนบัญชีที่ไม่ได้ใช้อาจยังมีผู้รับผิดชอบและเหตุผลรองรับ'),[
 R(('Recent use / accountable owner','มีการใช้ / มีผู้รับผิดชอบ'),('An owned production service account runs its approved job.','Service account มีทีมดูแลและทำงานที่อนุมัติอยู่'),('Activity does not remove the need to review access.','มีการใช้ก็ยังต้องทบทวนความเหมาะสมของสิทธิ์')),
 R(('No recent use / accountable owner','ไม่พบการใช้ระยะนี้ / มีผู้รับผิดชอบ'),('An approved recovery account is rarely needed.','บัญชีกู้คืนที่อนุมัติไว้อาจแทบไม่ได้ใช้'),('Validate its need and safeguards; inactivity is not automatic orphaning.','ตรวจความจำเป็นและการป้องกัน การไม่ใช้งานไม่ได้แปลว่าขาดผู้รับผิดชอบทันที')),
 R(('Recent use / missing accountability','มีการใช้ / ขาดผู้รับผิดชอบ'),('An old automated job still runs but no responsible owner is known.','งานอัตโนมัติเก่ายังรัน แต่ไม่ทราบผู้รับผิดชอบที่เหมาะสม'),('Investigate identity linkage, purpose and dependencies.','ตรวจการเชื่อม Identity วัตถุประสงค์ และระบบที่พึ่งพา')),
 R(('No recent use / missing accountability','ไม่พบการใช้ระยะนี้ / ขาดผู้รับผิดชอบ'),('A leftover account has neither a known owner nor recent activity.','บัญชีตกค้างไม่มีทั้งผู้รับผิดชอบที่ทราบและการใช้ในระยะนี้'),('Use authorized investigation and remediation, not blind record deletion.','ตรวจและแก้ตามอำนาจ ไม่ลบระเบียนโดยไม่พิจารณา'))],
 ('Activity and accountable ownership are independent dimensions, not a two-level risk score. Dormant or unused describes observed activity relative to a defined policy or context; orphaned describes missing appropriate ownership, governance or linkage to a current identity. These conditions can coexist, and an actively used service account can still be orphaned. Conversely, a rarely used recovery account may have a valid accountable owner and continuing approved purpose. Review purpose, responsible identity, permissions and dependencies before deciding what to retain or remove under policy. Do not define inactive accounts as necessarily owned, infer ownership from a successful login or delete every unused record automatically. The four examples in the table illustrate the independent questions; they do not set a universal inactivity threshold or guarantee that any cell is safe.',
 'การใช้งานกับความรับผิดชอบเป็นคนละคำถาม ไม่ใช่ตารางคะแนนความเสี่ยงสองระดับ Dormant หรือ Unused อธิบายการใช้ที่สังเกตได้เทียบกับนโยบายหรือบริบทที่กำหนด ส่วน Orphaned อธิบายการขาดผู้รับผิดชอบ การกำกับ หรือการเชื่อมกับ Identity ปัจจุบันที่เหมาะสม ทั้งสองสภาพเกิดร่วมกันได้ และ Service account ที่ยังมีงานใช้อยู่ก็อาจขาดผู้รับผิดชอบได้ ในทางกลับกัน บัญชีกู้คืนที่แทบไม่ได้ใช้อาจยังมีผู้รับผิดชอบและวัตถุประสงค์ที่อนุมัติ ควรตรวจวัตถุประสงค์ ผู้รับผิดชอบ สิทธิ์ และระบบที่พึ่งพา ก่อนตัดสินใจคงหรือถอนตามนโยบาย อย่านิยามว่าบัญชีไม่เคลื่อนไหวต้องมีเจ้าของเสมอ อย่าอนุมานว่ามีผู้รับผิดชอบเพียงเพราะ Login ได้ และอย่าลบทุกระเบียนที่ไม่ได้ใช้โดยอัตโนมัติ ตัวอย่างทั้งสี่แสดงคำถามที่เป็นอิสระต่อกัน ไม่ได้กำหนดช่วงเวลาไม่ใช้งานสากลหรือรับประกันว่าช่องใดปลอดภัย'),
 [('Usage: is the account being used?','การใช้งาน: มีการใช้บัญชีหรือไม่?'),('Accountability: who is responsible, and for what purpose?','ความรับผิดชอบ: ใครดูแล และใช้เพื่ออะไร?'),('Validate need and dependencies before remediation.','ตรวจความจำเป็นและระบบที่พึ่งพาก่อนแก้ไข')],
 ('Do not confuse “unused” with “unowned.”','อย่าสับสนระหว่าง “ไม่ได้ใช้งาน” กับ “ขาดผู้รับผิดชอบ”'),['d3-notes','d3-summary','identity-lifecycle'])

add('review-at-the-change',('Scheduled reviews do not replace change-triggered reassessment.','การทบทวนตามรอบไม่ทดแทนการตรวจเมื่อหน้าที่เปลี่ยน'),('Routine review and event-triggered review complement each other.','การทบทวนตามรอบและเมื่อมีเหตุเปลี่ยนแปลงช่วยเสริมกัน'),[
 R(('Routine review','ทบทวนตามรอบ'),('Use the organization’s policy and risk-based cadence.','ใช้รอบตามนโยบายและความเสี่ยงขององค์กร'),('A calendar entry alone does not enforce access.','การมีรอบในปฏิทินอย่างเดียวไม่ได้บังคับใช้สิทธิ์')),
 R(('Change-triggered reassessment','ตรวจเมื่อมีเหตุเปลี่ยนแปลง'),('Reassess changed duties, projects or contract need.','ตรวจเมื่อหน้าที่ โครงการ หรือความจำเป็นตามสัญญาเปลี่ยน'),('Do not leave known unjustified rights until the next scheduled review.','อย่าปล่อยสิทธิ์ที่รู้ว่าหมดความจำเป็นไว้จนถึงรอบถัดไป')),
 R(('Source example: six months later','ตัวอย่างต้นฉบับ: ผ่านไปหกเดือน'),('Finance access remained after the employee moved to IT.','พนักงานย้ายไป IT แต่สิทธิ์ Finance ยังอยู่'),('Elapsed story time, not the required review frequency.','เวลาที่ผ่านไปในเรื่อง ไม่ใช่ความถี่ที่ต้องทบทวน'))],
 ('Periodic reviews can discover changes or inappropriate access that were missed, but they do not replace authorized action when a relevant event is known. A new role, changed project assignment or ended contract can require reassessment and adjustment according to policy and risk. Record the trigger, current need, decision and verified result. The six months in the Finance-to-IT source example is elapsed time, not a review schedule recommendation. The course does not prescribe that all organizations review every ninety days or wait for certainty of harm before removing known unjustified rights. Automated event feeds can help initiate the process, but an HR status change or calendar reminder alone does not prove the applications have enforced the required change.',
 'การทบทวนตามรอบช่วยค้นหาการเปลี่ยนแปลงหรือสิทธิ์ไม่เหมาะสมที่อาจตกหล่น แต่ไม่ได้ทดแทนการดำเนินการตามอำนาจเมื่อทราบเหตุที่เกี่ยวข้องแล้ว การเปลี่ยน Role งานโครงการ หรือการสิ้นสุดสัญญาอาจต้องตรวจและปรับสิทธิ์ตามนโยบายและความเสี่ยง ควรบันทึกเหตุ ความจำเป็นปัจจุบัน ผลตัดสินใจ และผลตรวจยืนยัน เวลาหกเดือนในตัวอย่าง Finance ย้ายไป IT ไม่ใช่คำแนะนำเรื่องรอบ Review บทเรียนนี้ไม่ได้กำหนดให้ทุกองค์กรทบทวนทุกเก้าสิบวัน หรือรอให้มั่นใจว่าจะเกิดความเสียหายก่อนถอนสิทธิ์ที่รู้ว่าหมดความจำเป็นแล้ว ข้อมูลเหตุเปลี่ยนแปลงอัตโนมัติช่วยเริ่มกระบวนการได้ แต่การเปลี่ยนสถานะใน HR หรือข้อความเตือนจากปฏิทินเพียงอย่างเดียวไม่ได้พิสูจน์ว่าแอปต่าง ๆ ปรับสิทธิ์สำเร็จ'),
 [('Use policy-defined routine reviews.','ทบทวนตามรอบที่นโยบายกำหนด'),('Respond to relevant changes without waiting for that calendar date.','จัดการเหตุเปลี่ยนแปลงที่เกี่ยวข้องโดยไม่รอวันในปฏิทิน'),('Verify the enforced result.','ตรวจผลที่ระบบบังคับใช้จริง')],
 ('Review cadence is contextual; the six-month story is not a standard.','รอบทบทวนขึ้นกับบริบท เรื่องที่ผ่านมาหกเดือนไม่ใช่มาตรฐาน'),['d3-notes','d3-summary','identity-lifecycle'])

add('withdraw-without-erasing-history',('Withdraw access without erasing required evidence.','ถอนสิทธิ์ โดยไม่ทำลายหลักฐานที่ต้องเก็บ'),('Deprovisioning removes or disables unneeded access; record retention is a separate decision.','Deprovisioning ถอนหรือระงับสิทธิ์ที่หมดความจำเป็น ส่วนการเก็บระเบียนเป็นอีกเรื่องหนึ่ง'),[
 R(('Employee Termination','ถูกเลิกจ้าง'),('A departure can trigger access withdrawal.','การสิ้นสุดการจ้างอาจทำให้ต้องถอนสิทธิ์'),('Coordinate authorized timing and verification under policy.','ประสานเวลาและการตรวจผลตามนโยบายและอำนาจ')),
 R(('Employee Resignation','ลาออก'),('Reassess and withdraw access that should not continue.','ตรวจและถอนสิทธิ์ที่ไม่ควรใช้ต่อ'),('Do not retain unjustified access merely because departure is voluntary.','การออกโดยสมัครใจไม่ได้ทำให้เก็บสิทธิ์ที่ไม่จำเป็นไว้ได้')),
 R(('Role Change','เปลี่ยนบทบาท'),('Remove only rights that are no longer justified.','ถอนสิทธิ์ส่วนที่หมดความจำเป็น'),('An employee may still need an ordinary account for the new work.','พนักงานอาจยังต้องใช้บัญชีทั่วไปเพื่อทำงานใหม่')),
 R(('Contract Expiration','หมดสัญญา'),('End the access authorized for that contract.','ยุติสิทธิ์ที่ให้สำหรับสัญญานั้น'),('A contractor end date must reach the relevant access systems.','วันสิ้นสุดสัญญาต้องนำไปดำเนินการในระบบที่เกี่ยวข้อง')),
 R(('Disabling User Account','ระงับบัญชีผู้ใช้'),('Prevent further use of the relevant account.','ป้องกันการใช้บัญชีที่เกี่ยวข้องต่อ'),('Disabling is not the same as deleting every identity record.','ระงับบัญชีไม่เท่ากับลบทุกระเบียนของ Identity')),
 R(('Revoking Application Access','ถอนสิทธิ์แอปพลิเคชัน'),('Withdraw the relevant application rights.','ถอนสิทธิ์ในแอปที่เกี่ยวข้อง'),('Check downstream application grants and sessions.','ตรวจสิทธิ์และ Session ในแอปปลายทาง')),
 R(('Removing Group Memberships','ถอดสมาชิกกลุ่ม'),('Remove group memberships no longer required.','ถอดสมาชิกกลุ่มที่ไม่จำเป็นแล้ว'),('Verify which effective rights changed.','ตรวจว่าสิทธิ์ที่มีผลจริงเปลี่ยนอย่างไร')),
 R(('Revoking Privileged Access','ถอนสิทธิ์ระดับสูง'),('Remove obsolete administrative capability.','ถอนความสามารถดูแลระบบที่ไม่จำเป็นแล้ว'),('A move may withdraw admin rights while ordinary work continues.','การย้ายงานอาจถอนสิทธิ์ Admin โดยยังทำงานทั่วไปต่อได้'))],
 ('Deprovisioning removes or disables access when it is no longer justified. The source names four triggers and four possible activities, retained in the table; these are not eight universal sequential steps. The extent of removal depends on the event: an ended contract may require full withdrawal, while a role change may remove network administration but retain an ordinary employee account. Act with authorized timing according to policy and verify relevant accounts, applications, memberships, privileged rights and access paths. Access revocation is distinct from deleting a digital identity record or destroying audit history. Preserve required authorization and activity evidence under applicable retention and privacy policy; later archive or deletion decisions must follow those requirements. Neither a disabled-account flag nor an updated HR status is sufficient proof that all relevant access has ended.',
 'Deprovisioning ถอนหรือระงับ Access เมื่อไม่มีเหตุผลให้ใช้ต่อ ต้นฉบับระบุเหตุสี่อย่างและกิจกรรมที่อาจทำสี่อย่างซึ่งเก็บไว้ครบในตาราง ไม่ใช่แปดขั้นตอนเรียงลำดับที่ทุกองค์กรต้องทำเหมือนกัน ขอบเขตขึ้นกับเหตุ เช่น หมดสัญญาอาจต้องถอนสิทธิ์ทั้งหมดที่ให้ตามสัญญา ขณะที่ย้ายหน้าที่อาจถอน Network admin แต่ยังคงบัญชีพนักงานทั่วไปไว้ ให้ดำเนินการตามเวลาและอำนาจที่นโยบายกำหนด แล้วตรวจบัญชี แอป สมาชิกกลุ่ม สิทธิ์ระดับสูง และช่องทางเข้าถึงที่เกี่ยวข้อง การถอน Access ต่างจากการลบระเบียนตัวตนหรือทำลายประวัติ Audit ควรเก็บหลักฐานอนุมัติและกิจกรรมตามข้อกำหนดการเก็บรักษาและ Privacy ส่วนการ Archive หรือลบภายหลังต้องเป็นไปตามข้อกำหนดนั้น สถานะว่าบัญชีถูกระงับหรือข้อมูล HR เปลี่ยนแล้วอย่างเดียวจึงไม่พอยืนยันว่าการเข้าถึงทั้งหมดที่เกี่ยวข้องสิ้นสุดลง'),
 [('Remove access according to the actual event and authority.','ถอนตามเหตุจริงและอำนาจที่กำหนด'),('Verify relevant access paths, not just the HR record.','ตรวจช่องทางเข้าถึงที่เกี่ยวข้อง ไม่ใช่ดูเฉพาะระเบียน HR'),('Retain required evidence under policy.','เก็บหลักฐานที่จำเป็นตามนโยบาย')],
 ('Disable access ≠ delete all records.','ระงับสิทธิ์ ≠ ลบทุกระเบียน'),['d3-notes','d3-summary','identity-lifecycle'])

add('central-and-application-sessions',('A central disable does not prove every app session has ended.','ระงับบัญชีกลางแล้ว ไม่ได้ยืนยันว่าทุก Session ในแอปสิ้นสุดลง'),('In this observed case, an application still accepts a previously established session.','ในกรณีที่ตรวจพบนี้ แอปยังยอมให้ใช้ Session ที่เริ่มไว้ก่อนหน้า'),[
 R(('Central identity disabled','บัญชีกลางถูกระงับ'),('The central control records the account change.','ระบบกลางบันทึกการเปลี่ยนสถานะบัญชี'),('Do not infer the state of every separately managed session.','อย่าอนุมานสถานะของทุก Session ที่จัดการแยกต่างหาก')),
 R(('Existing application session','Session เดิมในแอป'),('The application may manage its session independently.','แอปอาจจัดการ Session ของตนแยกต่างหาก'),('Supported coordination can exist; behavior is not identical everywhere.','อาจมีกลไกประสานการยุติ Session แต่แต่ละระบบไม่ได้ทำงานเหมือนกันทั้งหมด')),
 R(('Supported withdrawal and verification','ถอนและตรวจผลด้วยกลไกที่ระบบรองรับ'),('Terminate or revoke the relevant session/grant and test denial.','ยุติหรือเพิกถอน Session/สิทธิ์ที่เกี่ยวข้อง แล้วตรวจว่าถูกปฏิเสธ'),('Check relevant authentication material and remaining access paths too.','ตรวจสิ่งที่ใช้ยืนยันตัวตนและช่องทางที่ยังเหลือด้วย'))],
 ('An application can manage its authenticated session separately from the central identity service. NIST SP 800-63C-4 explains that ending the identity-provider session does not necessarily terminate sessions at relying applications; supported end-session signaling may coordinate them. Likewise, a central account change is not proof that all previously issued sessions or other access paths are gone. This slide describes an observed residual session, not a rule that central disablement always fails. An authorized administrator should use supported withdrawal mechanisms for relevant application grants, sessions and authentication material, then verify the intended denial. Product capabilities and timing vary; do not promise instant global revocation or treat clearing a local browser screen as server-side termination. Protocol configuration and full tool architecture remain outside this lesson.',
 'แอปอาจจัดการ Session ที่ยืนยันตัวตนแล้วแยกจากบริการ Identity กลาง NIST SP 800-63C-4 อธิบายว่าการยุติ Session ที่ Identity provider ไม่จำเป็นต้องยุติ Session ในแอปที่อาศัยข้อมูลนั้นด้วย แม้บางระบบจะส่งสัญญาณประสานการยุติได้ เช่นเดียวกัน การเปลี่ยนสถานะบัญชีกลางไม่ได้ยืนยันว่า Session ที่ออกไว้หรือช่องทางเข้าถึงอื่นหมดไปแล้ว สไลด์นี้ระบุกรณีที่ตรวจพบ Session ค้าง ไม่ใช่กฎว่าระงับบัญชีกลางแล้วต้องล้มเหลวเสมอ ผู้ดูแลที่มีอำนาจควรใช้กลไกที่ระบบรองรับเพื่อถอนสิทธิ์ ยุติ Session และจัดการสิ่งที่ใช้ยืนยันตัวตนที่เกี่ยวข้อง แล้วตรวจว่าถูกปฏิเสธตามที่ต้องการ ความสามารถและเวลาที่มีผลแตกต่างกัน จึงไม่ควรรับประกันว่าจะเพิกถอนพร้อมกันทันทีทุกระบบ หรือถือว่าปิดหน้าบราวเซอร์แล้วเท่ากับยุติ Session ที่เซิร์ฟเวอร์ รายละเอียดตั้งค่า Protocol และสถาปัตยกรรมเครื่องมือไม่อยู่ในบทนี้'),
 [('Separate sessions may need coordinated withdrawal.','Session ที่แยกกันอาจต้องประสานการเพิกถอน'),('Use the actual system’s supported controls.','ใช้ Control ที่ระบบจริงรองรับ'),('Verify the intended access denial.','ตรวจว่าปฏิเสธการเข้าถึงได้ตามที่ต้องการ')],
 ('Check the application result; do not infer it from one central switch.','ตรวจผลที่แอป อย่าอนุมานจากสวิตช์กลางเพียงจุดเดียว'),['d3-notes','nist-federation'])

add('retire-a-workload-identity',('A retired workload should not leave active, unjustified access.','เลิกใช้ระบบงานแล้ว ไม่ควรทิ้งสิทธิ์ที่หมดความจำเป็นไว้'),('Review the bot’s purpose, responsible owner and dependencies before completing retirement.','ตรวจวัตถุประสงค์ ผู้รับผิดชอบ และระบบที่พึ่งพา Bot ก่อนดำเนินการเลิกใช้ให้ครบ'),[
 R(('Purpose and owner','วัตถุประสงค์และผู้รับผิดชอบ'),('The monthly reporting job has been retired.','งานรายงานรายเดือนนี้เลิกใช้แล้ว'),('The responsible team must account for remaining identity use.','ทีมที่รับผิดชอบต้องอธิบายการใช้ Identity ที่ยังเหลือ')),
 R(('Dependencies','ระบบที่พึ่งพา'),('Check which approved jobs still depend on the account or authentication material.','ตรวจว่างานที่อนุมัติใดยังพึ่งบัญชีหรือสิ่งที่ใช้ยืนยันตัวตนนี้'),('Plan authorized continuity changes without retaining unjustified access indefinitely.','วางแผนปรับเพื่อความต่อเนื่องตามอำนาจ ไม่ปล่อยสิทธิ์ที่ไร้เหตุผลไว้อย่างไม่มีกำหนด')),
 R(('Withdraw obsolete access','ถอนสิทธิ์ที่หมดความจำเป็น'),('Remove obsolete grants and retire relevant authentication material.','ถอนสิทธิ์ที่เลิกใช้และจัดการสิ่งที่ใช้ยืนยันตัวตนที่เกี่ยวข้อง'),('Use methods appropriate to the workload, not a universal human MFA prompt.','ใช้วิธีที่เหมาะกับระบบงาน ไม่สมมติว่าต้องตอบ MFA แบบมนุษย์ทุกกรณี')),
 R(('Verify and record','ตรวจผลและบันทึก'),('Check that no unjustified access path remains.','ตรวจว่าไม่เหลือช่องทางที่หมดความจำเป็น'),('Keep accountable retirement evidence under retention policy.','เก็บหลักฐานเลิกใช้ที่ระบุผู้รับผิดชอบตามนโยบายเก็บรักษา'))],
 ('Service accounts and bots need lifecycle governance even when they do not appear as employees in an HR departure list. When the reporting workload is retired, the accountable team should review the purpose, current usage and dependencies of its identity. Coordinate any justified service transition, withdraw obsolete permissions and retire relevant authentication material using the supported process, then verify no unjustified access path remains. Dependency analysis prevents avoidable disruption; it is not permission to keep an unmanaged privileged identity indefinitely. A change of human owner is also a reason to reassess responsibility, not automatically proof that the workload itself must end. Record the authorized action and result under retention policy. This is explicit official AI/service-account application guidance, without prescribing a vendor or a password-only authentication model.',
 'Service account และ Bot ต้องมีการกำกับตลอดวงจรชีวิต แม้ไม่ได้อยู่ในรายชื่อพนักงานออกจากงานของ HR เมื่องานรายงานนี้เลิกใช้ ทีมที่รับผิดชอบควรตรวจวัตถุประสงค์ การใช้ปัจจุบัน และระบบที่พึ่ง Identity นี้ ประสานการเปลี่ยนผ่านของบริการที่ยังมีเหตุผลรองรับ ถอน Permission ที่เลิกใช้ และจัดการสิ่งที่ใช้ยืนยันตัวตนตามกลไกที่รองรับ แล้วตรวจว่าไม่เหลือช่องทางเข้าถึงที่หมดความจำเป็น การวิเคราะห์ระบบที่พึ่งพาช่วยลดการหยุดชะงักที่เลี่ยงได้ แต่ไม่ได้อนุญาตให้ปล่อย Identity สิทธิ์สูงที่ขาดการกำกับไว้อย่างไม่มีกำหนด การเปลี่ยนผู้ดูแลมนุษย์เป็นเหตุให้ทบทวนความรับผิดชอบด้วย ไม่ได้พิสูจน์ว่างานอัตโนมัติต้องยุติเสมอ ให้บันทึกการดำเนินการตามอำนาจและผลตรวจตามนโยบายเก็บรักษา นี่คือการประยุกต์กับ AI/Service account จากแหล่งที่ระบุ ไม่ได้กำหนดผู้ขายหรือบังคับให้ทุกงานใช้ Password'),
 [('Workload purpose can end independently of employment.','ระบบงานอาจสิ้นสุดโดยไม่เกี่ยวกับการจ้างงาน'),('Dependencies require coordinated, authorized changes.','ระบบที่พึ่งพาต้องปรับอย่างประสานกันตามอำนาจ'),('Verify retirement and retain required evidence.','ตรวจผลการเลิกใช้และเก็บหลักฐานที่จำเป็น')],
 ('Service continuity needs an accountable plan, not indefinite orphaned access.','ความต่อเนื่องต้องมีแผนและผู้รับผิดชอบ ไม่ใช่ปล่อยสิทธิ์ที่ขาดการกำกับไว้ไม่มีกำหนด'),['isc2-ai-application','service-account-governance','identity-lifecycle'])

add('complete-offboarding-decision',('Finish the withdrawal, then verify the result.','ถอนสิทธิ์ให้ครบ แล้วตรวจผล'),('The contractor’s authorized end date has passed. The central account is disabled, but its old app session still works. You are authorized to complete removal now.','สัญญาสิ้นสุดแล้ว บัญชีกลางถูกระงับ แต่ Session เดิมในแอปยังใช้ได้ คุณมีอำนาจดำเนินการถอนสิทธิ์ให้ครบได้ทันที'),[
 R(('Assume central disablement is enough','ถือว่าระงับบัญชีกลางก็เพียงพอ'),('Close the ticket because the central account is disabled.','ปิด Ticket เพราะบัญชีกลางถูกระงับแล้ว'),('The observed application session contradicts complete withdrawal. A central status alone does not prove the intended denial at the application.','Session ในแอปที่ยังใช้ได้แสดงว่ายังถอนสิทธิ์ไม่ครบ สถานะบัญชีกลางอย่างเดียวไม่พิสูจน์ว่าแอปปฏิเสธการเข้าถึงแล้ว')),
 R(('Erase the identity history','ลบประวัติ Identity ทั้งหมด'),('Delete all identity and audit records to make a clean exit.','ลบระเบียน Identity และ Audit ทั้งหมดให้หมดร่องรอย'),('Destroying required evidence does not establish session revocation. Withdrawal and record retention are separate obligations under the stated policy.','ทำลายหลักฐานที่ต้องเก็บไม่ได้ยืนยันว่าเพิกถอน Session แล้ว การถอนสิทธิ์กับการเก็บระเบียนเป็นคนละหน้าที่ตามนโยบาย')),
 R(('Complete and verify authorized removal','ดำเนินการถอนและตรวจผลตามอำนาจ'),('Revoke remaining app access/session; verify denial and retain required evidence.','ถอนสิทธิ์/Session ที่ยังเหลือ ตรวจว่าถูกปฏิเสธ และเก็บหลักฐานที่จำเป็น'),('The contract has ended and you have removal authority. Use supported application controls, check other relevant access paths and verify the intended denial while retaining required records.','สัญญาสิ้นสุดแล้วและคุณมีอำนาจถอนสิทธิ์ ใช้ Control ของแอปที่รองรับ ตรวจช่องทางที่เกี่ยวข้องอื่น และยืนยันว่าถูกปฏิเสธ โดยยังเก็บระเบียนที่จำเป็น')),
 R(('Wait for the next scheduled review','รอทบทวนตามรอบถัดไป'),('Leave the session until the next periodic review.','ปล่อย Session ไว้จนถึงรอบ Review ถัดไป'),('A known contract end and observed residual access require the authorized action stated here. A future calendar review does not justify delaying it.','โจทย์ระบุว่าสัญญาจบและยังเข้าถึงได้ จึงต้องดำเนินการตามอำนาจที่ให้ไว้ รอบในปฏิทินภายหน้าไม่ใช่เหตุให้เลื่อนการถอนนี้'))],
 ('This authored scenario gives an authorized administrator a confirmed contractor end date and direct evidence that an existing application session remains usable after central disablement. Under the stated policy the administrator may complete withdrawal now. The supported action is to revoke the residual application access or session through appropriate controls, check other relevant access paths, verify the intended denial and retain required evidence. Do not declare success from the HR or central-account flag, destroy audit history or wait for the next routine review despite the known end of authorization. The example does not promise that every product supports identical revocation or immediate global propagation; an administrator must use the supported process and verify its result. All four reasons are available in Reading and Info as well as the interactive presentation.',
 'สถานการณ์ที่แต่งเพื่อการเรียนนี้ให้ข้อมูลวันสิ้นสุดสัญญาที่แน่นอนและหลักฐานว่า Session เดิมในแอปยังใช้ได้หลังระงับบัญชีกลาง โดยผู้ดูแลมีอำนาจดำเนินการถอนสิทธิ์ให้ครบได้แล้วตามนโยบาย แนวทางที่มีเหตุผลรองรับคือใช้ Control ที่เหมาะสมถอนสิทธิ์หรือ Session ที่ยังเหลือในแอป ตรวจช่องทางเข้าถึงอื่นที่เกี่ยวข้อง ยืนยันผลว่าถูกปฏิเสธ และเก็บหลักฐานที่จำเป็น ไม่ควรประกาศว่าสำเร็จจากสถานะ HR หรือบัญชีกลาง ไม่ควรทำลายประวัติ Audit หรือรอรอบ Review ทั้งที่ทราบว่าสิ้นสุดอำนาจใช้สิทธิ์แล้ว ตัวอย่างนี้ไม่ได้รับประกันว่าทุกผลิตภัณฑ์เพิกถอนได้เหมือนกันหรือส่งผลพร้อมกันทันทีทุกระบบ ผู้ดูแลต้องใช้กระบวนการที่รองรับและตรวจผลจริง Reading และ Info มีเหตุผลครบทั้งสี่ทางเลือกเช่นเดียวกับหน้าโต้ตอบ'),
 [('Authority has ended and removal is authorized.','สิทธิ์ตามสัญญาสิ้นสุดแล้ว และมีอำนาจถอน'),('The working app session is evidence of a remaining path.','Session ที่ยังใช้ได้เป็นหลักฐานว่ามีช่องทางเหลือ'),('Verification and record retention both matter.','ต้องตรวจผลและเก็บระเบียนที่จำเป็นควบคู่กัน')],
 ('Choose an action and review the reason. Reset lets you reconsider.','เลือกแนวทางและอ่านเหตุผล ใช้ Reset เมื่อต้องการพิจารณาใหม่'),['d3-notes','d3-summary','nist-federation','identity-lifecycle'])

