lesson=dict(schemaVersion=1,id=id,outlineId='isc2-cc-2026-09-01',domainId=3,primaryObjectiveId='3.1',objectiveIds=['3.1'],revision='1',status='published',title=P('Access Reviews, Changes & Deprovisioning','ทบทวน ปรับ และถอนสิทธิ์ตลอดวงจรชีวิต'),synopsis=P('Reassess changing needs, distinguish activity from ownership and verify authorized access withdrawal for people and workloads.','ทบทวนความจำเป็นที่เปลี่ยน แยกการใช้งานจากความรับผิดชอบ และตรวจผลการถอนสิทธิ์ของคนและระบบงาน'),outcomes=[P('Explain review findings and respond to role changes without accumulating unjustified rights.','อธิบายสิ่งที่ Review ตรวจพบและปรับเมื่อย้ายงานโดยไม่สะสมสิทธิ์ที่ไม่จำเป็น'),P('Distinguish inactivity, missing accountability, review decisions and applied changes.','แยกการไม่ใช้งาน การขาดผู้รับผิดชอบ ผลทบทวน และการปรับสิทธิ์จริง'),P('Complete authorized withdrawal, verify remaining paths and retain required evidence.','ถอนตามอำนาจให้ครบ ตรวจช่องทางที่เหลือ และเก็บหลักฐานที่จำเป็น')],prerequisites=[P('Recommended: Domain 3 Lesson 1 roles/provisioning and ordinary account/application access concepts.','แนะนำให้เรียน Domain 3 Lesson 1 เรื่อง Role/Provisioning และพื้นฐานบัญชี/การเข้าถึงแอป')],assets=[],references=refs,slides=slides,review=dict(reviewedRevision='1',evidencePath='docs/plans/isc2-cc-2026/domain-3-lesson-2-implementation-report.md',**{k:dict(status='approved',reviewer='Codex — assistant review; human acceptance pending',reviewedAt='2026-10-30') for k in ['technical','bilingual','rights']}))
